  ) values (
    'wbsa', 'bfb52589-7566-4347-95aa-03d696a1041e',
    'Whole-Body Systems Assessment',
    'A whole-body check-in across 16 connected functional systems, built to help surface patterns worth a closer look. This is wellness education, not a medical diagnosis.',
    'intake_questionnaire', 20, true, true, true, 1, true
