    ('Upper Digestive Function', 'How food sits with you after eating', 1),
    ('Lower Digestive & Elimination Function', 'Regularity, comfort, and change over time', 2),
    ('Blood Sugar & Energy Regulation', 'How steady your energy feels between meals', 3),
