    ('Thyroid & Metabolic-Related Observations', 'Temperature, weight, and energy rhythm', 9),
    ('Adrenal & Stress-Response Patterns', 'How your body handles daily demands', 10),
    ('Reproductive & Hormonal Patterns', 'Cycle, libido, and hormonal rhythm', 11),
    ('Neurological & Cognitive Patterns', 'Focus, memory, and nervous system signals', 12),
    ('Musculoskeletal & Connective-Tissue Patterns', 'Stiffness, joints, and how you move', 13),
    ('Skin, Hair & Nail Observations', 'Outward signals of what is going on inside', 14),
    ('Nutrient Insufficiency Patterns', 'What your everyday eating pattern suggests', 15),
    ('Recovery & Resilience Patterns', 'How well your body and mind bounce back', 16)
  ) as v(title, subtitle, display_order)
  returning id, title
)
